('00000000-0000-0000-0000-000000000000', 'Ist Assembler eine Hochsprache?', 2, '[{"text": "Nein", "correct": true, "because": "Low-Level-Sprache"}, {"text": "Ja", "correct": false, "because": "Nahe an Maschinencode"}]'),
