('00000000-0000-0000-0000-000000000000', 'Was ist bei Assembler unwichtig?', 4, '[{"text": "Prozessorregister", "correct": false, "because": "Kern der Programmierung"}, {"text": "Befehlssyntax", "correct": false, "because": "Grundlage"}, {"text": "Codeformatierung", "correct": true, "because": "Ästhetik irrelevant"}]'),
